insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d2027ed3-7670-4963-9212-4e48cccf8097', 'fr', 'Que se passe-t-il quand tu rebondis sur les fils au lieu de sauter à de nouvelles questions ?', '["La conversation paraît plus naturelle et moins comme un entretien", "Elle se sent écoutée parce que tu t’intéresses à ce qu’elle a partagé", "Les deux réponses ci-dessus"]'::jsonb, 'Rebondir sur les fils montre ta présence et ton attention ; fais du dernier détail qu’elle a donné ta prochaine étape.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('999bda2b-2b88-4a84-bd9c-d736ccb07089', 'fr', 'Elle dit : « Je travaille dans le marketing. » Quelle réponse rebondit sur un fil ?', '["« Cool. Tu viens d’où, à l’origine ? »", "« J’ai un ami dans le marketing aussi. Le monde est petit. »", "« Ah, sympa. Moi, je suis dans la finance. »", "« Le marketing, c’est intéressant. Quel genre : réseaux sociaux, marque, analyse de données ? »"]'::jsonb, 'Rebondir sur un fil, c’est creuser son sujet ; pose des questions précises sur ce qu’elle a mentionné.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2923827f-429f-4dd6-ac88-436a5a9dbbc6', 'fr', 'Comment choisir le fil à suivre ?', '["Choisir un détail qui t’intéresse", "Utiliser une liste de questions préparée", "Rebondir sur quelque chose de précis qu’elle a partagé"]'::jsonb, 'N’importe quel détail qu’elle donne peut faire avancer les choses ; choisis celui qui éveille ta curiosité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('29feaa96-2d35-4ba5-9ebd-71eb7f487487', 'fr', 'Pourquoi ne faire que poser des questions peut-il rendre une conversation tendue ?', '["Les questions ralentissent la conversation", "Les questions lui renvoient sans cesse la responsabilité", "Les questions paraissent récitées", "Les questions réduisent l’attirance"]'::jsonb, 'Trop de questions créent une dynamique où tu ne fais que prendre, et c’est elle qui porte la conversation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('52edb21f-05cb-41ea-a94c-5ec38eca6a8d', 'fr', 'Qu’apportent les affirmations et les observations que les questions n’apportent pas ?', '["Elles montrent ton assurance en partageant ton point de vue", "Elles montrent que tu es assez intéressant pour partager tes idées", "Elles ouvrent des portes pour répondre, sans exiger de réponse"]'::jsonb, 'Les observations lui donnent quelque chose à quoi réagir, sans le poids d’une question.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('89a9c6b7-ea88-49ca-a0b1-19c9f94287cd', 'fr', 'Quelles réponses sont des observations ou des affirmations plutôt que des demandes d’information ?', '["« On dirait que tu avais besoin de ce verre. »", "« Ça a l’air épuisant. »", "« Tu travailles souvent tard ? »", "« Ici, c’est la folie le week-end. »"]'::jsonb, 'Celles-ci apportent du contexte ou un point de vue au lieu de demander plus d’informations.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a8dcf867-454f-44e9-b824-f823389b43f0', 'fr', 'Qu’est-ce qui définit le mieux un bon élan dans une conversation ?', '["Parler avec assurance, sans pause", "La laisser tout mener", "Combler le silence le plus vite possible", "Un va-et-vient régulier où chacun apporte sa part"]'::jsonb, 'L’élan vient d’une participation partagée, pas d’un flot de paroles ni d’une passivité totale.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b838c1a-69b1-4328-9785-cd16d57ae3b6', 'fr', 'Elle parle d’un voyage récent. Tu es allé au même endroit. Comment pourrais-tu répondre ?', '["Lui raconter tout ce que tu as fait pendant ton voyage", "Dire « Ouais, j’y suis allé » et t’arrêter là", "Partager une phrase, puis l’inviter à développer"]'::jsonb, 'Une courte contribution suivie d’un espace pour elle garde un élan partagé.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2760f510-bd8b-4ac3-bab9-6e67951fb689', 'fr', 'Pourquoi monopoliser la conversation réduit-il son envie de s’investir ?', '["Ça l’empêche d’apporter sa part", "Ça crée un monologue à sens unique", "Ça montre que tu écoutes activement"]'::jsonb, 'Monopoliser la parole lui enlève toute place et casse l’équilibre de l’élan.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6e149fa3-93c4-42b2-9c8e-f7f88712cc49', 'fr', 'Elle finit de t’expliquer une décision difficile et te regarde. Quelle est la meilleure réponse ?', '["La rassurer tout de suite", "Lui donner un conseil immédiatement", "Marquer une courte pause, soutenir son regard, puis répondre", "Changer de sujet pour alléger l’ambiance"]'::jsonb, 'Une courte pause montre que tu assimiles ce qu’elle dit et l’invite à aller plus loin.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f100da89-837b-4ce4-89f0-13a05418c184', 'fr', 'Tu poses une question réfléchie. Elle prend le temps de réfléchir avant de répondre. Que fais-tu ?', '["Intervenir pour l’aider", "Reformuler la question", "Ajouter une autre question", "Laisser le silence et la laisser réfléchir"]'::jsonb, 'La laisser réfléchir sans pression montre ta patience et ton assurance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('af284377-c4c0-42ca-a6f4-112ce777e549', 'fr', 'Quand le silence est-il le plus efficace dans une conversation ?', '["Après qu’elle a partagé quelque chose de personnel", "Quand tu ne sais pas quoi dire", "Juste avant une affirmation réfléchie", "Pour éviter complètement d’apporter ta part"]'::jsonb, 'Le silence marche quand il laisse place à la réflexion ou donne du poids, pas quand il remplace l’échange.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5d75efc2-36fb-47a3-9f27-cb0833551415', 'fr', 'Qu’est-ce que le sous-texte dans une conversation ?', '["Les mots exacts prononcés", "Le sens émotionnel derrière les mots", "Seulement le volume de sa voix", "La longueur de ses phrases"]'::jsonb, 'Le sous-texte, c’est l’écart entre les mots dits et le ressenti derrière. Réponds à ça.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9fe24bb8-edce-4a11-ac05-37dcfca6822d', 'fr', 'Elle dit « Je viens d’emménager ici » d’un ton doux et hésitant. Quelle est une réponse attentive ?', '["« Tu viens d’où ? »", "« Ça te plaît pour l’instant ? »", "« Ça fait beaucoup de changements. Comment se passe la transition ? »", "« Tu fais quoi dans la vie ? »"]'::jsonb, 'Cette réponse reconnaît la dimension émotionnelle que son ton laisse entendre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4434c17e-e1bd-4981-8ea6-566ffaae5de4', 'fr', 'Quelles erreurs t’empêchent d’entendre le sous-texte ?', '["N’écouter que les mots-clés", "Préparer ta question suivante", "Faire attention au ton et au rythme"]'::jsonb, 'On rate le sous-texte quand on cherche à soutirer des informations au lieu d’être présent. Sois présent.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('69b81da3-8a21-43e7-9c1f-52aedcb7f44f', 'fr', 'Que veut dire écouter pour comprendre ?', '["Attendre poliment ton tour de parler", "Préparer une réponse réfléchie pendant qu’elle parle", "Approuver tout ce qu’elle dit", "Être pleinement présent à ce qu’elle exprime"]'::jsonb, 'Écouter pour comprendre, c’est faire passer la compréhension avant la préparation de ta réponse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94878e49-fd86-4e6f-8398-cdb055f272a3', 'fr', 'Pourquoi préparer ta réponse pendant qu’elle parle réduit-il le lien ?', '["Ça ralentit la conversation", "Ça te fait paraître récité", "Ça augmente les silences", "Ça détourne ton attention de ce qu’elle veut dire"]'::jsonb, 'Préparer ta réponse tourne ton attention vers toi et te fait rater les nuances et le sous-texte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e596b988-c6fd-4182-add2-2c2b0eeb4cc4', 'fr', 'Quelles réponses montrent que tu as écouté pour comprendre ?', '["Proposer tout de suite des solutions", "Nommer le ressenti qu’elle a laissé entendre", "Marquer une pause avant de répondre", "Rebondir directement sur sa dernière phrase"]'::jsonb, 'La compréhension vient de la présence, pas du fait de tout régler ou d’étaler ta perspicacité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5e09607d-070f-41c5-af20-c696a61f1329', 'fr', 'À quoi sert le fait de reconnaître sa réponse avant de continuer la conversation ?', '["À montrer que ses mots ont été compris et qu’ils comptent", "À ralentir volontairement la conversation", "À paraître émotionnellement intelligent", "À éviter de poser des questions de relance"]'::jsonb, 'La reconnaissance montre que son message a été reçu avant que la conversation avance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0af9f869-b543-4bea-bfe5-e3c0c0722302', 'fr', 'Elle dit : « Ma sœur et moi, on ne se voit plus beaucoup. » Meilleure réponse ?', '["« C’est la vie. »", "« Elle a quel âge ? »", "« La distance, ça peut être dur. Vous vous parlez souvent, toutes les deux ? »", "« Elle habite où, maintenant ? »"]'::jsonb, 'Nommer la réalité émotionnelle avant de poser une question garde le moment humain.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0810f6d9-5a61-4b89-b159-0607132c5f66', 'fr', 'Quelles phrases sont des marques de reconnaissance ?', '["« Ça a dû demander des efforts. »", "« Pourquoi tu as fait ça ? »", "« Je comprends que ça ait compté pour toi. »", "« Cool. »"]'::jsonb, 'La reconnaissance salue le sens ou l’effort, pas seulement le contenu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8e246a4f-c248-490c-956f-77029e0a2ad4', 'fr', 'Que sont les signes d’écoute non verbaux ?', '["Des signaux corporels qui montrent ton implication et ton attention", "Des expressions du visage qui montrent tes réactions à ce qu’elle dit", "Des ajustements de posture qui montrent une écoute active", "Toutes les réponses ci-dessus"]'::jsonb, 'Les signes non verbaux montrent que tu es présent et que tu assimiles ce qu’elle dit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('61372c16-e1e3-47b9-b21c-d9331ef4e852', 'fr', 'Elle raconte une histoire avec de plus en plus d’énergie. Quels signes non verbaux accompagnent le mieux le moment ?', '["Une posture immobile pour ne pas la distraire", "Des sourires et des expressions qui réagissent", "Regarder ailleurs pour lui laisser de l’espace", "Des encouragements verbaux sans bouger"]'::jsonb, 'T’accorder physiquement à son énergie montre que tu suis son histoire émotionnellement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9fcc9a77-636d-4e32-833f-dd1e41b91be5', 'fr', 'Quels signaux trahissent la distraction ?', '["Un visage inexpressif", "Un corps tourné ailleurs", "Reproduire ses expressions", "Balayer la salle du regard"]'::jsonb, 'Une immobilité sans réaction passe souvent pour du désintérêt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e90c6c9-0d3b-47fc-b3ac-599c201f184d', 'fr', 'Quels éléments est-il le plus important d’accorder au début ?', '["La profondeur émotionnelle", "Le débit de parole", "Le volume et l’énergie", "Toutes les réponses ci-dessus"]'::jsonb, 'L’aisance du début vient du fait de s’accorder en profondeur émotionnelle, en rythme et en énergie.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6886b3ac-3f9a-4fba-ad87-515db908bb79', 'fr', 'Elle parle avec émotion d’un événement récent. Que pourrais-tu faire en premier ?', '["T’accorder à son ton émotionnel avec empathie", "Répondre par un conseil pratique", "Passer à une histoire drôle", "Poser des questions factuelles"]'::jsonb, 'Reflète son ton pour montrer que vous êtes en phase avant d’aller ailleurs.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('003c10ec-d480-4896-916d-26f2d942ba10', 'fr', 'Pourquoi t’accorder d’abord à sa profondeur et à sa façon de parler aide-t-il à créer de la complicité ?', '["Ça signale une ressemblance et détend son système nerveux", "Ça montre que tu es à l’écoute de son énergie du moment", "Ça réduit les frictions dues à un décalage", "Ça fait tout de suite passer à des sujets plus profonds"]'::jsonb, 'S’accorder vous met en phase, ce qui rend naturel le fait d’aller plus loin.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3327c759-7a65-49ec-96b3-d70b813c73ef', 'fr', 'Quelle est la façon la plus efficace de partager une histoire ?', '["Partager moins de détails personnels", "Partager des émotions sans contexte", "Partager des expériences avec du recul et une résolution", "Éviter complètement la vulnérabilité"]'::jsonb, 'Partager efficacement inclut du recul et une résolution ; partage ce que tu en as appris.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c32cb2cd-cf15-4d66-aa1f-8bc019d02b51', 'fr', 'Début de conversation. Elle te demande : « Tu fais quoi dans la vie ? » Quelle réponse est la mieux ajustée ?', '["« Je bosse dans la tech, mais je déteste ça et je ne sais pas quoi faire à la place. »", "« Je bosse dans la tech. C’est exigeant, mais ça m’apprend beaucoup de discipline. »", "« C’est compliqué. Je n’aime pas trop en parler. »"]'::jsonb, 'Cette réponse reconnaît la réalité tout en montrant du recul. Elle suscite la curiosité, pas l’inquiétude.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2924bec5-27b6-4372-95e0-97a1b87cd7f5', 'fr', 'Pourquoi partager une expérience digérée vaut-il mieux qu’une expérience non digérée en début de conversation ?', '["Ça montre de la lucidité sur toi et de l’évolution", "Ça évite de lui faire porter un poids émotionnel", "Ça invite à la proximité sans créer de pression", "Ça déverse des difficultés non résolues pour attirer la compassion"]'::jsonb, 'Les expériences digérées créent du lien ; les expériences non digérées créent du malaise.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('72b691fd-5105-42a5-b902-f35bd796089d', 'fr', 'Quel est le but principal quand tu racontes une histoire dans une conversation ?', '["L’impressionner avec ton parcours", "Rivaliser avec ses histoires", "Meubler en attendant qu’elle reparle", "Révéler quelque chose d’important sur toi"]'::jsonb, 'Un instantané clair et sincère l’aide à te comprendre vite.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('26a750bf-98fb-4c3c-a099-407b3b3aabb9', 'fr', 'Elle te demande comment tu es arrivé à ton travail actuel. Que pourrais-tu partager ?', '["Toute ta chronologie depuis le lycée", "Seulement ton poste actuel, sans contexte", "Un moment clé qui t’a fait changer de voie"]'::jsonb, 'Concentre-toi sur un moment qui compte pour montrer clairement qui tu es et garder son attention.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2330422b-5fb8-4763-a6cc-a1631f85f12d', 'fr', 'Quels éléments sont essentiels pour qu’une histoire retienne l’attention ?', '["Une mise en place pour donner vite le contexte", "Un conflit ou une tension pour créer un enjeu", "Une résolution ou une leçon", "Les dates et les noms exacts"]'::jsonb, 'Concentre-toi sur ce que tu veux qu’elle comprenne, pas sur tout ce qui s’est passé.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1ce28b32-b0c8-4221-b1ff-d3645dd9b96d', 'fr', 'Pourquoi des histoires sans lien avec elle créent-elles de la distance plutôt que du lien ?', '["Elles te font paraître centré sur toi et pas intéressé par elle", "Tu as parlé de toi sans l’inclure", "Elle attend son tour au lieu de s’intéresser à ton histoire"]'::jsonb, 'Partager sans relier crée de la distance ; invite son point de vue pour garder le lien vivant.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3f38e00a-0c18-4520-94c4-258ed755d84d', 'fr', 'Quelle fin relie l’histoire à elle ? Toi : « Quand je suis arrivé ici, les premiers mois, je me sentais assez isolé. »', '["« Bref, ça s’est arrangé pour moi. »", "« Cette ville est dure au début. »", "« Déménager, c’est toujours difficile. »", "« Et toi, comment se passe ton adaptation pour l’instant ? »"]'::jsonb, 'Inviter directement son point de vue transforme ton expérience en terrain commun.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d6f93781-4c91-4d3e-835b-28dd4c18773b', 'fr', 'Comment relier tes histoires à elle ?', '["Lui demander comment elle réagirait dans la situation que tu as décrite", "Rattacher l’histoire à quelque chose qu’elle a mentionné plus tôt", "La complimenter sur une qualité ou un point de vue en rapport"]'::jsonb, 'Le lien se crée quand ton histoire devient un pont, pas un point final.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('445fcfa0-4ff7-4518-ac38-f732d3f82c0a', 'fr', 'Elle partage spontanément des détails personnels et rit facilement. Qu’est-ce que ça indique ?', '["Elle est juste polie", "Le lien a assez de poids pour que tu concrétises", "Elle veut que tu partes", "L’échange est encore superficiel"]'::jsonb, 'Des confidences spontanées et de l’énergie montrent que le moment est venu de concrétiser.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('22126888-2232-418e-83ad-f3149c24f572', 'fr', 'Elle répond avec chaleur et développe ce que tu dis. Qu’est-ce que ça indique ?', '["Le lien a assez de poids pour que tu concrétises", "Elle supporte la conversation", "Elle veut faire court", "La discussion est encore superficielle"]'::jsonb, 'La chaleur et le fait de développer montrent un fort investissement ; le moment est venu de concrétiser.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8c9143a9-92d6-4ec0-bd1d-cc131e69c354', 'fr', 'Quels sont les signes clés que le moment est venu de concrétiser ?', '["Elle donne des réponses courtes et polies", "Elle apporte plus que nécessaire", "Elle te pose des questions sur toi", "Elle montre une présence et une curiosité qui durent"]'::jsonb, 'Quand elle s’investit, s’intéresse à toi et reste impliquée, le moment est venu de concrétiser.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('372fbba5-b4e8-4738-9cf6-186872aed9ae', 'fr', 'Pourquoi rattacher ta sortie à quelque chose dont vous avez parlé ?', '["Pour paraître attentionné", "Pour créer une raison naturelle de donner suite", "Pour prouver que tu faisais attention", "Pour augmenter tout de suite l’attirance"]'::jsonb, 'Rappeler un détail partagé donne une raison naturelle de reprendre contact.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4bf82e54-bc68-47b4-954e-9a2f34ad7cee', 'fr', 'Vous avez eu une bonne conversation sur son prochain voyage. Quelle est la meilleure façon de partir ?', '["« Ravi de t’avoir rencontrée, prends soin de toi »", "« Je vais te laisser »", "Dire au revoir vite pour éviter la gêne", "Faire référence au voyage et proposer d’en reparler plus tard"]'::jsonb, 'Rappeler quelque chose qui lui tenait à cœur fait vivre l’échange au-delà de l’au revoir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b6859e08-892e-4454-a9e6-c9d9f7f344eb', 'fr', 'Quels détails vaut-il mieux utiliser pour terminer un échange ?', '["Un projet qu’elle a mentionné", "Une blague partagée", "Une observation neutre", "Quelque chose qui l’enthousiasmait"]'::jsonb, 'Les moments émotionnels ou partagés créent une continuité plus forte qu’un détail neutre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('10646abd-5ffe-4d87-9ebb-9d70bfea0218', 'fr', 'Sur quoi se décide-t-elle quand tu cherches à concrétiser ?', '["Si tu es quelqu’un avec qui construire une relation", "Si l’étape suivante lui paraît confortable", "Si tu es différent des autres hommes", "Si elle veut quelque chose de sérieux"]'::jsonb, 'Les premiers oui sont une question de confort, pas d’engagement. Rends l’étape suivante facile.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8d044d58-aac0-440d-9742-83bb3888a6e8', 'fr', 'Conversation légère sur un marché. Bonne ambiance. Quelle est la meilleure façon de concrétiser ?', '["« On devrait aller dîner un de ces jours »", "« D’habitude, je ne fais pas ça, mais je peux avoir ton numéro ? »", "« Je t’envoie l’adresse dont on a parlé »", "« Tu es libre ce week-end ? »"]'::jsonb, 'Ça prolonge le moment sans en faire un engagement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8a141571-c267-4806-9868-387cdb482491', 'fr', 'Quelles façons de concrétiser mettent peu de pression et rendent le oui facile ?', '["« Je t’envoie l’adresse dont on a parlé »", "« On devrait prévoir un dîner demain »", "« On reprend ça une autre fois »", "« Je peux t’inviter à sortir vendredi ? »"]'::jsonb, 'Ces options invitent à continuer sans demander d’engagement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66ba6667-2abd-42f6-a901-d96277d04433', 'fr', 'Comment transformer des questions en suite proposée comme une évidence ?', '["« Ça te dirait d’aller boire un café ? » devient « Allons boire un café »", "« Je peux avoir ton numéro ? » devient « C’est quoi, ton numéro ? »", "« Tu veux qu’on se revoie ? » devient « On se revoit »", "Toutes les réponses ci-dessus"]'::jsonb, 'Proposer la suite comme une évidence marche parce que ça enlève l’hésitation du moment.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d70c3efb-944b-4b7a-82a9-48ba274ccb86', 'fr', 'Pourquoi demander la permission pour concrétiser affaiblit-il souvent un bon échange ?', '["Ça sonne trop formel", "Ça active son esprit d’analyse au lieu de la laisser dans le moment", "Ça te fait paraître arrogant", "Ça réduit le lien émotionnel"]'::jsonb, 'Une question invite à évaluer, ce qui peut casser des sensations qui étaient déjà positives.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c0286e42-af7f-43c7-ac69-9ab7c6a2e05a', 'fr', 'Quelles phrases proposent la suite comme une évidence ?', '["« Ça te dirait, peut-être, qu’on se voie un de ces jours ? »", "« Allons boire un café cette semaine. »", "« Mets ton numéro, je t’écris. »", "« Tu serais à l’aise pour qu’on échange nos numéros ? »"]'::jsonb, 'Proposer la suite comme une évidence marche parce que ça enlève l’hésitation du moment.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b4f4d3f5-96e1-4f85-964d-0f77451b74c5', 'fr', 'Que signale généralement une baisse d’énergie dans une conversation ?', '["Elle a perdu tout intérêt", "L’échange a échoué", "Tu as dit quelque chose de travers", "L’élan est retombé et il faut réorienter"]'::jsonb, 'Les baisses d’énergie sont des transitions normales, pas des signes de rejet.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8c543af2-ac46-444f-8c77-92edfd929224', 'fr', 'Tu remarques que ses réponses raccourcissent après un changement de sujet. Quelle est une bonne réaction ?', '["Poser une question plus profonde pour relancer l’élan", "Faire remarquer la gêne", "Marquer une courte pause et passer à un sujet plus léger et neutre", "Arrêter de parler et la laisser réorienter"]'::jsonb, 'Réorienter calmement relance le rythme sans ajouter de pression.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1cdf68f6-8aa9-43b3-9ce5-b644e615778c', 'fr', 'Une baisse d’énergie peut arriver parce que :', '["un sujet s’est épuisé", "quelqu’un a abordé un point neutre ou sensible", "le rythme a naturellement changé", "l’attirance a disparu d’un coup"]'::jsonb, 'Une baisse d’énergie signale généralement un changement, pas une perte d’attirance ; ajuste le sujet ou le rythme.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39b1d59b-f33e-478c-9666-991b209c27d4', 'fr', 'Quelle règle intérieure aide le mieux à ne pas être d’accord sans perdre le lien ?', '["Ne jamais contester ses opinions", "Toujours expliquer ton raisonnement en entier", "Garder la conversation légère à tout prix", "Voir les différences comme quelque chose à comprendre, pas à vaincre"]'::jsonb, 'Comprendre préserve le lien. Gagner, non.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c7c5b822-4135-4f6f-8bdf-de37566401d8', 'fr', 'Elle donne un avis avec lequel tu n’es pas d’accord. Qu’est-ce que tu dois éviter ?', '["Demander : « Qu’est-ce qui te fait voir les choses comme ça ? »", "En remettre une couche pour la convaincre que tu as raison", "Reconnaître son point de vue avant de donner le tien", "Rester curieux de son point de vue"]'::jsonb, 'Imposer ton point de vue te rend querelleur et casse le rythme de la conversation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('01a6207d-b8f9-4037-8efa-858f6eca585f', 'fr', 'Pourquoi un désaccord bien géré peut-il augmenter l’attirance ?', '["Il crée du drame", "Il montre ton authenticité", "Il montre que tu ne joues pas un rôle pour être approuvé", "Il établit ta supériorité"]'::jsonb, 'On réagit à l’authenticité, pas aux efforts pour obtenir l’approbation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bcc09860-096f-4e3f-af27-42276cd9f883', 'fr', 'Pourquoi est-il important de t’associer à des émotions positives ?', '["Les émotions créent des associations plus fortes avec toi", "Les sensations positives lui donnent envie de passer plus de temps avec toi", "Les deux réponses ci-dessus"]'::jsonb, 'L’attirance se construit sur ce qu’elle ressent en ta présence, pas seulement sur le contenu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f1e9a61d-15cb-4f8b-af34-a49ba9147cfd', 'fr', 'Tu sens que la conversation devient pesante. Quelle est la meilleure chose à faire ?', '["Changer brusquement de sujet", "Apporter de la logique ou des conseils", "Introduire du jeu ou de l’imagination", "T’excuser pour l’ambiance"]'::jsonb, 'La légèreté relance le ton émotionnel sans attirer l’attention sur la baisse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ed64c038-1dd6-4294-ab5d-a11f9b7c1095', 'fr', 'Quelles réactions dans la conversation t’associent à des émotions positives ?', '["Imaginer un soulagement ou un plaisir à venir", "Être joueur sans forcer les blagues", "Minimiser ses inquiétudes", "Poser des questions qui font réfléchir"]'::jsonb, 'Ces réactions font monter l’état émotionnel sans nier ce qu’elle vit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0031e3a0-ef4a-44e3-a000-6ae183b1956c', 'fr', 'Pourquoi se précipiter pour répondre réduit-il souvent le lien ?', '["Ça sonne récité", "Ça lui enlève l’espace pour continuer", "Ça paraît trop logique", "Ça raccourcit la conversation"]'::jsonb, 'La vitesse peut encombrer le moment et l’empêcher de développer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('01f54d1a-679b-4a40-80b2-cdc59c6849ef', 'fr', 'Que se passe-t-il quand tu te tais trop souvent dans une conversation ?', '["Elle doit porter l’échange", "Ça crée du mystère", "Ça crée de l’attente", "Ça montre de l’assurance"]'::jsonb, 'Un silence sans contribution lui fait porter injustement tout l’effort.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('021ce377-a3dd-4de9-9114-c7227778650f', 'fr', 'Elle dit « Moi, je vois ça autrement » et marque une pause. Quelle est la meilleure chose à faire ?', '["La corriger gentiment", "Lui demander ce qui a forgé son point de vue", "Défendre tout de suite ta position", "Changer de sujet pour éviter la friction"]'::jsonb, 'Inviter son point de vue garde un échange coopératif.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('03069501-c343-419c-9422-a171d3aefb45', 'fr', 'Qu’est-ce qui fait qu’un désaccord abîme le lien ?', '["Avoir des avis opposés", "Exprimer des opinions tranchées", "Faire passer le fait d’avoir raison avant le lien", "Parler de sujets sérieux"]'::jsonb, 'Ce n’est pas le désaccord qui crée la tension, c’est le besoin d’avoir raison.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0fb4b26d-dc3b-4250-9c5f-8ff9ea4885aa', 'fr', 'Pourquoi concrétiser par une petite demande sans pression marche-t-il mieux au début ?', '["Ça ressemble à la suite naturelle du moment", "Ça lui permet de dire oui sans avoir à trop réfléchir", "Ça déclenche son réflexe de protection"]'::jsonb, 'Une demande sans pression fait baisser les défenses ; garde tes demandes petites pour que le oui soit naturel.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('15ae2762-769f-4714-8d54-0a1d42a10930', 'fr', 'Qu’est-ce qui résume le mieux l’écoute non verbale ?', '["Laisser ton corps réagir visiblement à ses mots", "Éviter de l’interrompre", "Jouer l’expressif", "Garder le silence"]'::jsonb, 'L’écoute se montre par le corps avant de s’exprimer par les mots.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1a509b2e-e316-4bf7-a46a-0c9212bf889f', 'fr', 'Qu’est-ce qui rend une demande facile plutôt qu’exigeante quand tu cherches à concrétiser ?', '["Formuler ta demande pour que dire oui soit le plus simple", "Proposer plusieurs options pour qu’elle se sente maîtresse de la situation", "Présenter la décision en mettant en avant les avantages"]'::jsonb, 'Le but est de rendre le oui facile en enlevant la pression et en restant simple.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1b58b79f-3bec-4098-a37d-6b534a17056a', 'fr', 'Elle sourit naturellement et interrompt ce qu’elle faisait pour se concentrer sur toi. Qu’est-ce que ça veut dire ?', '["Elle est courtoise, mais pas intéressée", "Il faut d’abord plus de conversation légère", "Elle s’investit, et le moment est venu de concrétiser", "Elle est prête à mettre fin à l’échange"]'::jsonb, 'Un sourire sincère et une attention entière montrent que le moment est venu de concrétiser.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1c45a74c-59e6-49a8-abc6-c4f1e648d603', 'fr', 'Qu’est-ce qui casse le rythme d’une conversation ?', '["Quelqu’un qui parle trop sans s’arrêter", "Quelqu’un qui se tait et n’apporte rien", "Changer souvent de sujet avant d’en avoir fait le tour", "Toutes les réponses ci-dessus"]'::jsonb, 'Un bon rythme vient du fait de savoir quand parler et quand s’arrêter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('20617380-7250-45ce-9ef3-db838e43f344', 'fr', 'Elle dit « Le boulot a été chargé » en soupirant et en se recroquevillant. Que signale probablement ce comportement ?', '["Elle aime être productive", "Elle veut des conseils", "Elle change de sujet", "Elle laisse entendre de la fatigue ou du stress"]'::jsonb, 'Les signaux non verbaux en disent souvent plus que les mots eux-mêmes.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('26b9d0d1-6a3e-46d5-8be6-4fce70caa793', 'fr', 'Elle dit qu’elle commence un cours de poterie la semaine prochaine. Quelles sorties fonctionnent bien ?', '["« Bonne chance pour la poterie ! »", "« Un cours de poterie ? Il faudra que tu me montres ce que tu fais. »", "« J’ai envie de savoir comment se passe le premier cours. »", "« Génial ! On devrait se voir un de ces jours. »"]'::jsonb, 'Rappeler un fil donne une raison naturelle de reprendre contact.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('27419754-77e6-40e3-9216-e374c74f4e85', 'fr', 'Quelle est la clé d’une conversation équilibrée ?', '["Mêler questions, observations et affirmations", "N’utiliser que des questions pour que ça coule", "Apporter tes propres idées et ton attention", "La laisser fournir tout le contenu"]'::jsonb, 'L’équilibre vient d’une participation partagée, pas du fait de ne faire que prendre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2bd11bb2-0b86-43aa-b35b-b9370dcdcbdc', 'fr', 'Elle plaisante gentiment sur sa journée. Quelle est la meilleure réponse ?', '["Parler d’une difficulté personnelle sérieuse", "Te taire et la laisser mener", "Lui poser une question profonde sur ses valeurs", "T’accorder à son humour et ajouter un petit détail joueur"]'::jsonb, 'T’accorder à sa légèreté garde le rythme intact et préserve l’élan.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30047758-bc26-4c9c-b253-e6f994f1b01c', 'fr', 'Quand est-il approprié de partager des difficultés non digérées ?', '["Une fois qu’une vraie confiance et des bases solides se sont installées", "Jamais, il faut toujours digérer une expérience avant de la partager", "Quand tu as vite besoin de son soutien émotionnel"]'::jsonb, 'Partager une expérience non digérée demande des bases assez solides pour en porter le poids.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3133663f-3070-4a86-ace7-3cb3f7ad86cc', 'fr', 'Elle raconte en soupirant une expérience difficile. Qu’est-ce que tu dois éviter ?', '["Dire : « Ça a l’air dur. Qu’est-ce qui t’a aidée à t’en sortir ? »", "Sauter à : « Tu as essayé de faire comme ça ? »", "Remarquer : « Je comprends que ça ait été difficile. »", "Demander : « Qu’est-ce que tu as ressenti ? »"]'::jsonb, 'Un conseil sans reconnaissance donne l’impression que tu n’as pas saisi ce qu’elle voulait dire.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('31d09412-eae6-4340-9ae4-3e41fb01548a', 'fr', 'Elle a dit adorer un groupe que vous aimez tous les deux. Au moment de partir, que pourrais-tu faire ?', '["Dire « Ravi de t’avoir rencontrée. »", "Faire référence au groupe et proposer d’échanger vos numéros pour vous partager de la musique", "Poser une dernière question sans rapport"]'::jsonb, 'Utilise un détail partagé au moment de partir pour préserver le lien et l’élan.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('334df846-2984-4745-ad56-48b235d5dc09', 'fr', 'Pourquoi acquiescer pour éviter le désaccord affaiblit-il l’attirance ?', '["Ça paraît malhonnête", "Ça trahit de l’insécurité ou une recherche d’approbation", "Ça réduit la profondeur de la conversation", "Toutes les réponses ci-dessus"]'::jsonb, 'Éviter toute différence te fait disparaître dans le décor et t’enlève ton authenticité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('33959938-2cf9-429c-889b-15d1b785f535', 'fr', 'Quelle est la principale différence entre écouter pour répondre et écouter pour comprendre ?', '["Être centré sur toi ou être centré sur elle", "Le niveau d’assurance", "La vitesse de réponse", "La quantité de paroles"]'::jsonb, 'La différence tient à l’endroit où se trouve ton attention pendant l’échange.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('353e58e9-544b-4f89-8b9f-2806e9bbc67f', 'fr', 'Quelle psychologie explique qu’une petite demande marche mieux qu’une grosse proposition ?', '["On dit oui plus facilement quand la demande paraît sans pression", "Une petite demande montre ton assurance, parce que tu ne dépends pas du résultat", "Un faible enjeu réduit la peur du refus des deux côtés"]'::jsonb, 'Une demande sans pression fait baisser les défenses ; garde tes demandes petites pour que le oui soit naturel.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('35bf5d25-82d5-4369-ade9-a66744b2cd83', 'fr', 'Quelle question intérieure t’aide à choisir la bonne histoire à raconter ?', '["« Est-ce que c’est impressionnant ? »", "« Est-ce que je raconte tout ? »", "« Quelle est la seule chose que je veux qu’elle comprenne ? »", "« Ça fait combien de temps que je parle ? »"]'::jsonb, 'Concentre-toi sur ce que tu veux qu’elle comprenne, pas sur tout ce qui s’est passé.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('36112ad3-3e6a-4b43-8ba4-e67ceaa9859d', 'fr', 'Tu remarques sa coque de téléphone originale. Quelle réponse est une observation ?', '["« Tu l’as trouvée où, cette coque ? »", "« Elle est vraiment cool, cette coque. »", "« Il te plaît, ton téléphone ? »", "« C’est quel modèle, ton téléphone ? »"]'::jsonb, 'Une observation montre ton attention et lui donne quelque chose à quoi répondre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3722ef90-5c5e-45fb-bb2f-2f8a5e572077', 'fr', 'Quelle est la différence clé entre partager une expérience digérée et une expérience non digérée ?', '["La digérée est toujours positive ; la non digérée est négative", "La digérée, ce sont des leçons tirées ; la non digérée, une douleur non résolue", "La digérée crée de la pression ; la non digérée crée la confiance"]'::jsonb, 'Partage la leçon, pas la blessure, pour ne pas lui faire porter un poids émotionnel.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('37f350f5-2279-4994-9c9e-3ad922169129', 'fr', 'Pourquoi rebondir sur les fils évite-t-il la lassitude de la conversation de surface ?', '["Tu explores des sujets qui comptent au lieu d’échanges superficiels", "Rebondir sur ses fils crée un vrai échange au lieu d’un jeu de questions-réponses forcé", "Rebondir montre que tu es impliqué et que tu as écouté ce qu’elle avait à dire", "Toutes les réponses ci-dessus"]'::jsonb, 'Rebondir sur les fils approfondit les sujets, enlève l’effet entretien et augmente son investissement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('38aecf14-80ce-4eef-8327-98612dfd5568', 'fr', 'Elle raconte une histoire, et tu as envie de la rapprocher de ta propre expérience. Meilleure chose à faire ?', '["Raconter ton histoire juste après", "Te retenir et d’abord refléter ce qu’elle a partagé", "Changer de sujet pour garder l’élan", "Donner un conseil pour apporter quelque chose"]'::jsonb, 'Refléter ce qu’elle dit avant de parler de toi garde l’attention sur le fait de la comprendre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
